100 * (
  1 -
  (
    (
      (sum(rate(cadence_errors{deployment=~"$deployment", cadence_service=~"cadence-frontend|cadence_frontend", signalname!~".+"}[$__rate_interval])) or vector(0))
    )
    /
    (
      (sum(rate(cadence_requests{deployment=~"$deployment", cadence_service=~"cadence-frontend|cadence_frontend", signalname!~".+"}[$__rate_interval])) or vector(0))
    )
  )
)

100 * (
  1 -
  (
    (
      sum by (operation) (
        rate(cadence_errors{
          deployment=~"$deployment",
          cadence_service=~"cadence-frontend|cadence_frontend",
          operation=~"$procedure",
          signalname!~".+"
        }[$__rate_interval])
      )
      or on (operation)
      (
        sum by (operation) (
          rate(cadence_requests{
            deployment=~"$deployment",
            cadence_service=~"cadence-frontend|cadence_frontend",
            operation=~"$procedure",
            signalname!~".+"
          }[$__rate_interval])
        ) * 0
      )
    )
    /
    sum by (operation) (
      rate(cadence_requests{
        deployment=~"$deployment",
        cadence_service=~"cadence-frontend|cadence_frontend",
        operation=~"$procedure",
        signalname!~".+"
      }[$__rate_interval])
    )
  )
)

histogram_quantile(
  0.99,
  sum by (operation, le) (
    rate(cadence_latency_ns_bucket{
      deployment=~"$deployment",
      cadence_service=~"cadence-frontend|cadence_frontend",
      operation=~"$procedure"
    }[$__rate_interval])
  )
)

histogram_quantile(
  0.999,
  sum by (operation, le) (
    rate(cadence_latency_ns_bucket{
      deployment=~"$deployment",
      cadence_service=~"cadence-frontend|cadence_frontend",
      operation=~"$procedure"
    }[$__rate_interval])
  )
)

histogram_quantile(
  0.5,
  sum by (operation, le) (
    rate(cadence_latency_ns_bucket{
      deployment=~"$deployment",
      cadence_service=~"cadence-frontend|cadence_frontend",
      operation=~"$procedure"
    }[$__rate_interval])
  )
)

topk(
  30,
  (
    max_over_time(
      (
        sum by (host) (
          memory_gc_cpu_total{
            cadence_service=~"cadence[-_]frontend",
            deployment=~"$deployment"
          }
        )
      )[1m:]
    )
    /
    max_over_time(
      (
        sum by (host) (
          memory_cpu_total{
            cadence_service=~"cadence[-_]frontend",
            deployment=~"$deployment"
          }
        )
      )[1m:]
    )
  )
)

